-- 2026-11-18: the Education Hub's sample catalog for the two workforce demos built before demos seeded one
-- (src/lib/workforce/demo-training.ts). Additive; skips a demo that already has training. Applied to production 2026-11-18.
insert into "TrainingOffering" (id, "institutionId", source, title, provider, summary, skills, industries, functions, levels, hours, "priceCents", "wioaEligible", "ncCustom", assignment, status, "createdBy", "createdAt", "updatedAt")
select v.* from "Institution" i cross join lateral (values (gen_random_uuid()::text, i.id, 'UNIVERSITY', 'Certificate in project management', 'Louisville area community college (sample)', 'Evening certificate: planning, budgets, risk and leading a team through delivery. Prepares for the CAPM exam.', ARRAY['Project management','Budgeting','Risk management']::text[], '{}'::text[], ARRAY['Operations','Engineering']::text[], ARRAY['Individual contributor','Manager']::text[], 90, 240000, true, false, 'ASSIGNED', 'ACTIVE', 'demo', now(), now()),
(gen_random_uuid()::text, i.id, 'UNIVERSITY', 'Healthcare administration certificate', 'Louisville regional university (sample)', 'For people moving into hospital and clinic operations: revenue cycle, compliance and scheduling.', ARRAY['Revenue cycle','Healthcare compliance','Scheduling']::text[], ARRAY['Healthcare & Hospital Systems']::text[], ARRAY['Administration','Operations']::text[], '{}'::text[], 120, 380000, true, false, 'ASSIGNED', 'ACTIVE', 'demo', now(), now()),
(gen_random_uuid()::text, i.id, 'UNIVERSITY', 'Executive leadership program', 'Louisville regional university (sample)', 'Six weekends on strategy, finance for non-finance leaders and leading change.', ARRAY['Strategy','Change management','Finance for leaders']::text[], '{}'::text[], '{}'::text[], ARRAY['Director or above']::text[], 48, 650000, false, false, 'LISTED', 'ACTIVE', 'demo', now(), now()),
(gen_random_uuid()::text, i.id, 'THIRD_PARTY', 'Data analytics with spreadsheets and SQL', 'Online course provider (sample)', 'Self-paced: cleaning data, pivot tables, SQL queries and a dashboard you can show an employer.', ARRAY['SQL','Excel','Data visualization']::text[], '{}'::text[], ARRAY['Finance','Operations','Data & Analytics','Marketing']::text[], ARRAY['Individual contributor']::text[], 60, 29900, false, false, 'ASSIGNED', 'ACTIVE', 'demo', now(), now()),
(gen_random_uuid()::text, i.id, 'THIRD_PARTY', 'Supply chain and logistics fundamentals', 'Professional association (sample)', 'Planning, inventory and transportation basics, with a certificate from a professional body.', ARRAY['Inventory management','Demand planning','Logistics']::text[], ARRAY['Transportation & Logistics','Manufacturing & Industrial']::text[], ARRAY['Operations']::text[], '{}'::text[], 40, 89500, true, false, 'LISTED', 'ACTIVE', 'demo', now(), now()),
(gen_random_uuid()::text, i.id, 'THIRD_PARTY', 'Customer success management', 'Online course provider (sample)', 'Onboarding, renewals and account health for people moving from support or sales into customer success.', ARRAY['Account management','Customer onboarding','Renewals']::text[], ARRAY['Technology & Software']::text[], ARRAY['Customer Success','Sales']::text[], ARRAY['Individual contributor','Manager']::text[], 25, 19900, false, false, 'LISTED', 'ACTIVE', 'demo', now(), now()),
(gen_random_uuid()::text, i.id, 'LOCAL', 'AI tools for your job', 'Built by NextChapter for this region (sample)', 'Four short sessions on using AI assistants for writing, analysis and research in the work people already do.', ARRAY['AI tools','Prompt writing','Research']::text[], '{}'::text[], '{}'::text[], '{}'::text[], 6, 0, false, true, 'ASSIGNED', 'ACTIVE', 'demo', now(), now()),
(gen_random_uuid()::text, i.id, 'LOCAL', 'Job search bootcamp', 'Louisville job center (sample)', 'Two weeks: résumé, LinkedIn, interviewing and a weekly search plan, run by the region’s own career coaches.', ARRAY['Interviewing','Résumé writing','Networking']::text[], '{}'::text[], '{}'::text[], '{}'::text[], 16, 0, true, false, 'LISTED', 'ACTIVE', 'demo', now(), now())) v(id, "institutionId", source, title, provider, summary, skills, industries, functions, levels, hours, "priceCents", "wioaEligible", "ncCustom", assignment, status, "createdBy", "createdAt", "updatedAt")
where i.slug in ('demo-one-louisville-16870','demo-kentuckianaworks-d7645') and i."isDemo"
and not exists (select 1 from "TrainingOffering" t where t."institutionId" = i.id)
returning "institutionId";
